package app.streamnest;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;
final class WatchingRegression {
 static Bundle run(Instrumentation test)throws Exception{Context c=test.getTargetContext();WatchSync.pending=true;WatchSync.testPairingCode=WatchSyncCrypto.create();PlaybackSettingsActivity[] settings={null};String code=WatchSync.testPairingCode;
 try{WatchingActivity.install(c);HomeRegression.check(WatchingActivity.enabled(c),"Not default on");SyncGroup.update(c,"Watching verification");HomeRegression.check(SyncGroup.current!=null,"Fixture group unavailable");settings[0]=(PlaybackSettingsActivity)test.startActivitySync(new Intent(c,PlaybackSettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("activityTitle","Synthetic watching fixture").putExtra("activityKind","animes").putExtra("season",1).putExtra("episode",104));
 test.runOnMainSync(()->{WatchingActivity.begin(settings[0]);WatchingActivity.report(settings[0],"playing");});Thread.sleep(12000);java.lang.reflect.Field sent=WatchingActivity.class.getDeclaredField("sent");sent.setAccessible(true);HomeRegression.check(sent.get(null)!=null,"Live watching report was not acknowledged");
 // Verify the native off switch separately from diagnostic consent.
 test.runOnMainSync(()->{java.util.ArrayList<android.view.View> found=new java.util.ArrayList<>();settings[0].getWindow().getDecorView().findViewsWithText(found,"Share watching activity",android.view.View.FIND_VIEWS_WITH_TEXT);HomeRegression.check(found.size()==1,"Watching switch missing");android.widget.CheckBox toggle=(android.widget.CheckBox)found.get(0);HomeRegression.check(toggle.isChecked(),"Watching switch not default on");toggle.performClick();HomeRegression.check(!WatchingActivity.enabled(c),"Off choice not saved");WatchingActivity.report(settings[0],"playing");});Thread.sleep(1200);WatchingActivity.install(c);HomeRegression.check(!WatchingActivity.enabled(c),"Install reenabled sharing");Bundle b=new Bundle();b.putString("result","PASS: native default-on choice, real group registration, live playback report acknowledgement, independent settings off switch and retained off choice");return b;
 }finally{WatchingActivity.setEnabled(c,false);Thread.sleep(1000);if(settings[0]!=null)test.runOnMainSync(()->settings[0].finish());try{SyncGroup.call(c,code,"DELETE",new JSONObject().put("deviceId",SyncGroup.deviceId(c)));}catch(Exception ignored){}WatchSync.testPairingCode=null;WatchSync.pending=false;}}
}
